import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_exponent(n, min_exp, max_exp):
    if n == 0:
        return 0

    if n < min_exp:
        return -1

    max_count = 0

    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_exp = rng.randint(3, 10)
    max_exp = rng.randint(20, 40)
    n = rng.randint(50, 100)

    answer = find_max_exponent(n, min_exp, max_exp)

    check = -1
    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of distinct powers of 2 where the exponent ranges from {min_exp} to {max_exp} (inclusive). "
        f"What is the maximum number of distinct powers of 2 that can be selected such that no exponent exceeds the total {n} and all selected exponents sum to exactly {n}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "induction"


def find_max_subsets(n, min_subset_sum, max_subset_sum, target_value):
    if n == 0:
        return 0

    if n < min_subset_sum:
        return -1

    max_count = 0

    for subset_sum in range(min_subset_sum, max_subset_sum + 1):
        if subset_sum <= n:
            remaining_n = n - subset_sum
            count = find_max_subsets(remaining_n, min_subset_sum, subset_sum - 1, target_value)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(10, 50)
    min_subset_sum = rng.randint(3, 10)
    max_subset_sum = rng.randint(15, 30)
    target_value = rng.randint(30, 60)

    answer = find_max_subsets(n, min_subset_sum, max_subset_sum, target_value)

    check = -1
    for subset_sum in range(min_subset_sum, max_subset_sum + 1):
        if subset_sum <= n:
            remaining_n = n - subset_sum
            count = find_max_subsets(remaining_n, min_subset_sum, subset_sum - 1, target_value)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of integers ranging from 1 to {n}. What is the maximum number of distinct subsets that can be selected such that the sum of any subset ranges from {min_subset_sum} to {max_subset_sum} (inclusive), no subset sum exceeds the target divisor sum {target_value}, and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "sequence"
SKILL = "induction"


def find_max_divisors(target, min_divisor_sum, max_divisor_sum):
    if target == 0:
        return 0

    if target < min_divisor_sum:
        return -1

    max_count = 0

    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target:
            remaining_target = target - divisor_sum
            count = find_max_divisors(remaining_target, min_divisor_sum, divisor_sum - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_divisor_sum = rng.randint(5, 20)
    max_divisor_sum = rng.randint(30, 50)
    target_value = rng.randint(30, 60)

    answer = find_max_divisors(target_value, min_divisor_sum, max_divisor_sum)

    check = -1
    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target_value:
            remaining_target = target_value - divisor_sum
            count = find_max_divisors(remaining_target, min_divisor_sum, divisor_sum - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of integers where the sum of any subset of divisors ranges from {min_divisor_sum} to {max_divisor_sum} (inclusive). "
        f"What is the maximum number of distinct divisors that can be selected such that no subset sum exceeds the target divisor sum {target_value} and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)
